// One page load of one Ashmolean show page, through the sweep's own bridge,
// timing every request. Diagnostic only; writes nothing to the run folders.
process.chdir('/home/user/Cat-Search-Project/scraper');
const { chromium } = require('/home/user/Cat-Search-Project/node_modules/playwright');
const S = require('/home/user/Cat-Search-Project/scraper/sweep_prototype.js');
const URL = process.argv[2] || 'https://www.ashmolean.org/exhibition/colonial-views-of-india-impey-photographs';

(async () => {
  const browser = await chromium.launch({ executablePath: S.resolveChromium(), headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const context = await browser.newContext();
  await S.installNetworkBridge(context);
  const page = await context.newPage();
  const t0 = Date.now(); const at = () => ((Date.now() - t0) / 1000).toFixed(1);
  const reqs = new Map();
  page.on('request', r => reqs.set(r, { url: r.url(), type: r.resourceType(), start: at() }));
  page.on('requestfinished', r => { const x = reqs.get(r); if (x) x.end = at(); });
  page.on('requestfailed', r => { const x = reqs.get(r); if (x) { x.end = at(); x.fail = r.failure() && r.failure().errorText; } });
  page.on('domcontentloaded', () => console.log(`DOMContentLoaded at ${at()}s`));
  page.on('load', () => console.log(`load at ${at()}s`));
  const tick = setInterval(() => {
    const open = [...reqs.values()].filter(x => !x.end && x.type !== 'image' && x.type !== 'font' && x.type !== 'media');
    console.log(`${at()}s: ${reqs.size} requests, ${open.length} waiting${open.length ? ' e.g. ' + open.slice(0, 3).map(x => x.url.slice(0, 90)).join(' | ') : ''}`);
  }, 5000);
  try {
    await page.goto(URL, { waitUntil: 'load', timeout: 90000 });
  } catch (e) { console.log('goto: ' + e.message.split('\n')[0]); }
  const text = await page.evaluate(() => document.body ? document.body.innerText.length : 0).catch(() => -1);
  clearInterval(tick);
  console.log(`body text chars: ${text}`);
  const rows = [...reqs.values()].filter(x => !['image', 'font', 'media'].includes(x.type));
  const slow = rows.map(x => ({ ...x, dur: x.end ? x.end - x.start : null }))
    .filter(x => x.dur === null || x.dur > 2 || x.fail).sort((a, b) => (b.dur ?? 999) - (a.dur ?? 999));
  console.log(`\nslow (>2s), failed or never finished — ${slow.length} of ${rows.length}:`);
  for (const x of slow) console.log(`  ${x.start}s → ${x.end ?? 'NEVER'}${x.fail ? ' FAILED ' + x.fail : ''}  ${x.type}  ${x.url.slice(0, 120)}`);
  await browser.close();
})();

